//! Parity of the JDK 25 time-zone rules (`rucene_test_framework::jdk::time_zone`,
//! generated by `tools/gen/TimeZoneRules.java`) with `java.util.TimeZone`
//! and `GregorianCalendar`: for every ID of `TimeZone.getAvailableIDs()`,
//! the `HOUR_OF_DAY` of every instant of the grid `TimeZoneOracle` builds
//! (see its documentation and the oracle `README.md`) digests as Java's does
//! in `tests/fixtures/time_zone_hours.tsv`.

mod oracle_support;

use oracle_support::rows;
use randomizedtesting::jdk::random::JdkRandom;
use rucene_test_framework::jdk::time_zone::{gregorian_calendar_hour_of_day, zone_info, ZoneInfo};
use rucene_test_framework::util::TestUtil;

const DAY: i64 = 86_400_000;
/// `TimeZoneOracle.YEARS`.
const YEARS: [i32; 18] = [
    2037,
    2038,
    2039,
    2040,
    2087,
    2088,
    2100,
    2101,
    2400,
    2401,
    9999,
    10000,
    100_000,
    1_000_000,
    10_000_000,
    100_000_000,
    292_278_993,
    292_278_994,
];
/// `TimeZoneOracle.MAX_MINUS`.
const MAX_MINUS: [i64; 10] = [
    0, 1, 999, 3_599_999, 3_600_000, 46_799_999, 46_800_000, 50_400_000, 86_399_999, 86_400_000,
];

/// `LocalDate.of(year, 1, 1).toEpochDay() * DAY`.
fn jan1(year: i32) -> i64 {
    let y = i64::from(year) - 1;
    let fixed = 365 * y + y.div_euclid(4) - y.div_euclid(100) + y.div_euclid(400) + 1;
    (fixed - 719_163) * DAY
}

/// `TimeZoneOracle.grid(tz, row)`.
fn grid(tz: &ZoneInfo, row: i64) -> Vec<i64> {
    let mut g = vec![i64::MIN, i64::MIN + 1, -1, 0, 1];
    g.extend(MAX_MINUS.iter().map(|k| i64::MAX - k));
    for t in tz.transition_instants() {
        g.extend([t - 1, t, t + 1]);
    }
    if tz.has_last_rule() {
        for year in YEARS {
            let lo = jan1(year);
            let hi = if year == 292_278_994 {
                i64::MAX
            } else {
                jan1(year + 1)
            };
            let mut x = lo;
            while x < hi {
                let y = if hi - x > DAY { x + DAY } else { hi };
                if tz.get_offset(y) != tz.get_offset(x) {
                    let (mut a, mut c) = (x, y);
                    let oa = tz.get_offset(a);
                    while c - a > 1 {
                        let m = a + (c - a) / 2;
                        if tz.get_offset(m) == oa {
                            a = m;
                        } else {
                            c = m;
                        }
                    }
                    g.extend([c - 1, c]);
                }
                x = y;
            }
        }
    }
    let r = JdkRandom::new(row);
    for _ in 0..64 {
        g.push(TestUtil::next_long(&r, 0, i64::MAX));
    }
    g
}

/// The FNV-1a 64-bit digest of the little-endian bytes of each (instant,
/// hour) pair.
fn digest(tz: &ZoneInfo, grid: &[i64]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    let mut b = |v: u8| {
        h ^= u64::from(v);
        h = h.wrapping_mul(0x0100_0000_01b3);
    };
    for &instant in grid {
        let hour = gregorian_calendar_hour_of_day(tz, instant);
        instant.to_le_bytes().into_iter().for_each(&mut b);
        hour.to_le_bytes().into_iter().for_each(&mut b);
    }
    h
}

#[test]
fn hour_of_day_matches_java_for_every_zone() {
    let rows = rows("time_zone_hours.tsv");
    assert_eq!(
        rows.len(),
        rucene_test_framework::jdk::time_zone_available_ids().len(),
        "one row per available ID"
    );
    let mut mismatches = Vec::new();
    let mut instants = 0;
    for (row, r) in rows.iter().enumerate() {
        let tz = zone_info(&r[0]).unwrap_or_else(|| panic!("no rules for {}", r[0]));
        let g = grid(tz, row as i64);
        instants += g.len();
        let actual = format!("{}\t{:016x}", g.len(), digest(tz, &g));
        let expected = format!("{}\t{}", r[1], r[2]);
        if actual != expected {
            mismatches.push(format!("{}: expected {expected}, got {actual}", r[0]));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} zones differ:\n{}",
        mismatches.len(),
        rows.len(),
        mismatches.join("\n")
    );
    assert!(instants > 250_000, "{instants} instants");
}

#[test]
fn time_zone_offsets_follow_the_zone() {
    use rucene_test_framework::util::lucene_test_case::LuceneTestCase;
    // 2026-07-01T00:00:00Z and 2026-01-01T00:00:00Z.
    let (summer, winter) = (1_782_864_000_000, 1_767_225_600_000);
    let tz = LuceneTestCase::random_time_zone(&JdkRandom::new(1));
    assert_eq!(tz.get_id(), "Africa/El_Aaiun");
    let berlin = zone_info("Europe/Berlin").unwrap();
    assert_eq!(berlin.get_offset(summer), 7_200_000);
    assert_eq!(berlin.get_offset(winter), 3_600_000);
    let sydney = zone_info("Australia/Sydney").unwrap();
    assert_eq!(sydney.get_offset(summer), 36_000_000);
    assert_eq!(sydney.get_offset(winter), 39_600_000);
    assert_eq!(gregorian_calendar_hour_of_day(sydney, winter), 11);
}
